-- Catálogo AUTOMÁTICO: todos los permisos de AOSP (androguard 4.1.4, API 4 a 36; gana el nivel más nuevo).
-- Cubre cualquier permiso estándar de Android aunque no tengamos una explicación escrita a mano.
-- severity y weight salen del protectionLevel oficial (regla en docs/fuentes.md).
-- Nunca pisa las filas curadas (curated = true): esas las maneja 02-catalogo-curado.sql.
ON CONFLICT (android_name) DO UPDATE SET
  friendly_title = EXCLUDED.friendly_title,
  explanation = EXCLUDED.explanation,
  severity = EXCLUDED.severity,
  weight = EXCLUDED.weight,
  icon = EXCLUDED.icon,
  protection_level = EXCLUDED.protection_level,
  source = EXCLUDED.source
WHERE permission_catalog.curated = false;
